import { type Attribute, type Prim, type Stage, Typed } from 'typescript-usd/usd'

/**
 * A node-graph is a container for shading nodes, as well as other 
 * node-graphs. It has a public input interface and provides a list of public 
 * outputs.
 *
 * <b>Node Graph Interfaces</b>
 *
 * One of the most important functions of a node-graph is to host the "interface"
 * with which clients of already-built shading networks will interact.  Please
 * see \ref UsdShadeNodeGraph_Interfaces "Interface Inputs" for a detailed
 * explanation of what the interface provides, and how to construct and
 * use it, to effectively share/instance shader networks.
 *
 * <b>Node Graph Outputs</b>
 *
 * These behave like outputs on a shader and are typically connected to an 
 * output on a shader inside the node-graph.
 */
export class NodeGraph extends Typed {
  static readonly typeName: string = "NodeGraph"

  static get(stage: Stage, path: string): NodeGraph {
    return new NodeGraph(stage.getPrim(path), stage)
  }
  static define(stage: Stage, path: string): NodeGraph {
    return new NodeGraph(stage.definePrim(path, "NodeGraph"), stage)
  }

  isValid(): boolean {
    return super.isValid() && this.prim.isA(NodeGraph.typeName)
  }

  static getSchemaAttributeNames(includeInherited = true): string[] {
    const names = includeInherited
      ? []
      : []
    return names
  }

  // --(BEGIN CUSTOM CODE)--
  // UsdShadeNodeGraph::ConnectableAPI (nodeGraph.cpp:125-129).
  connectableAPI(): ConnectableAPI { return new ConnectableAPI(this._prim, this._stage) }

  // UsdShadeNodeGraph::CreateOutput / GetOutput / GetOutputs / CreateInput /
  // GetInput / GetInputs / GetInterfaceInputs (nodeGraph.cpp:131-212):
  // through the ConnectableAPI.
  createOutput(name: string, typeName = 'token'): ShadeOutput {
    return this.connectableAPI().createOutput(name, typeName)
  }
  getOutput(name: string): ShadeOutput { return this.connectableAPI().getOutput(name) }
  getOutputs(onlyAuthored = true): ShadeOutput[] { return this.connectableAPI().getOutputs(onlyAuthored) }
  createInput(name: string, typeName: string): ShadeInput {
    return this.connectableAPI().createInput(name, typeName)
  }
  getInput(name: string): ShadeInput { return this.connectableAPI().getInput(name) }
  getInputs(onlyAuthored = true): ShadeInput[] { return this.connectableAPI().getInputs(onlyAuthored) }
  getInterfaceInputs(): ShadeInput[] { return this.getInputs() }

  static is(prim: Prim): boolean { return prim.typeName === NodeGraph.typeName }

  // Every prim path strictly under `primPath` (recursive), matching
  // UsdPrim::GetDescendants order (depth-first, parents before children).
  private static _descendants(stage: Stage, primPath: string): string[] {
    const out: string[] = []
    const walk = (p: string) => {
      for (const child of stage.getChildPrimPaths(p)) {
        out.push(child)
        walk(child)
      }
    }
    walk(primPath)
    return out
  }

  // The non-transitive consumers map for one node-graph: for each of its
  // interface inputs, the descendant inputs that connect directly back to it.
  // Mirrors _ComputeNonTransitiveInputConsumersMap.
  private static _computeNonTransitive(
    stage: Stage, nodeGraphPath: string,
  ): InterfaceInputConsumersMap {
    const result: InterfaceInputConsumersMap = new Map()
    const ngPrim = stage.getPrim(nodeGraphPath)
    if (ngPrim) for (const inputName of getInputNames(ngPrim)) result.set(inputName, [])

    for (const descPath of NodeGraph._descendants(stage, nodeGraphPath)) {
      const prim = stage.getPrim(descPath)
      if (!prim || !isConnectable(prim.typeName)) continue

      for (const internalInput of getInputNames(prim)) {
        const conns = stage.get(`${descPath}.inputs:${internalInput}`)?.getConnections() ?? []
        for (const connPath of conns) {
          const source = parseSourcePath(connPath)
          // The source must be an INPUT on the node-graph itself.
          if (source && source.sourceType === 'input' && source.primPath === nodeGraphPath) {
            const list = result.get(source.name)
            if (list) list.push({ primPath: descPath, name: internalInput })
          }
        }
      }
    }
    return result
  }

  // Collect the non-transitive maps of every nested node-graph reachable as a
  // consumer, keyed by node-graph prim path. Mirrors
  // _RecursiveComputeNodeGraphInterfaceInputConsumers.
  private static _recursiveNodeGraphConsumers(
    stage: Stage,
    inputConsumersMap: InterfaceInputConsumersMap,
    nodeGraphInputConsumers: Map<string, InterfaceInputConsumersMap>,
  ): void {
    for (const consumers of inputConsumersMap.values()) {
      for (const consumer of consumers) {
        const prim = stage.getPrim(consumer.primPath)
        if (prim && isNodeGraphType(prim.typeName)) {
          if (!nodeGraphInputConsumers.has(consumer.primPath)) {
            const irMap = NodeGraph._computeNonTransitive(stage, consumer.primPath)
            nodeGraphInputConsumers.set(consumer.primPath, irMap)
            NodeGraph._recursiveNodeGraphConsumers(stage, irMap, nodeGraphInputConsumers)
          }
        }
      }
    }
  }

  // Resolve a single consumer through nested node-graphs to leaf consumers.
  // Mirrors _ResolveConsumers.
  private static _resolveConsumers(
    stage: Stage,
    consumer: InterfaceInputConsumer,
    nodeGraphInputConsumers: Map<string, InterfaceInputConsumersMap>,
    resolved: InterfaceInputConsumer[],
  ): void {
    const prim = stage.getPrim(consumer.primPath)
    if (!prim || !isNodeGraphType(prim.typeName)) {
      resolved.push(consumer)
      return
    }
    const inputConsumers = nodeGraphInputConsumers.get(consumer.primPath)
    if (!inputConsumers) { resolved.push(consumer); return }
    const nested = inputConsumers.get(consumer.name)
    if (nested === undefined) { resolved.push(consumer); return }
    if (nested.length === 0) {
      // A node-graph input with no consumers resolves to itself.
      resolved.push(consumer)
    } else {
      for (const nestedConsumer of nested) {
        NodeGraph._resolveConsumers(stage, nestedConsumer, nodeGraphInputConsumers, resolved)
      }
    }
  }

  // For each interface input of this node-graph, the inputs that consume it.
  // With `computeTransitiveConsumers`, consumers that are themselves
  // node-graph interface inputs are expanded to their own (leaf) consumers.
  // Mirrors UsdShadeNodeGraph::ComputeInterfaceInputConsumersMap.
  computeInterfaceInputConsumersMap(
    computeTransitiveConsumers = false,
  ): InterfaceInputConsumersMap {
    const result = NodeGraph._computeNonTransitive(this._stage, this.path)
    if (!computeTransitiveConsumers) return result

    const nodeGraphInputConsumers = new Map<string, InterfaceInputConsumersMap>()
    NodeGraph._recursiveNodeGraphConsumers(this._stage, result, nodeGraphInputConsumers)
    if (nodeGraphInputConsumers.size === 0) return result

    const resolvedMap: InterfaceInputConsumersMap = new Map()
    for (const [inputName, consumers] of result) {
      const resolved: InterfaceInputConsumer[] = []
      for (const consumer of consumers) {
        NodeGraph._resolveConsumers(this._stage, consumer, nodeGraphInputConsumers, resolved)
      }
      resolvedMap.set(inputName, resolved)
    }
    return resolvedMap
  }
}


// nodeGraph.cpp:360-386: NodeGraphs are containers (of nodes) and exhibit
// encapsulation behavior, with the default connection rules.
registerConnectableAPIBehavior(TfType.findByName('UsdShadeNodeGraph'),
  new ConnectableAPIBehavior(true /*isContainer*/, true /*requiresEncapsulation*/))

// UsdShadeNodeGraph — a container of shading nodes with interface
// inputs/outputs that pass values through its boundary.
// Reference: pxr/usd/usdShade/nodeGraph.h

import { ConnectableAPI, getInputNames, parseSourcePath, type ShadeInput, type ShadeOutput } from './connectableAPI.ts'
import { Type as TfType } from 'typescript-usd/tf'
import { ConnectableAPIBehavior, registerConnectableAPIBehavior } from './connectableAPIBehavior.ts'

// A consumer of an interface input: the bare input name (inputs:NAME) on the
// prim at `primPath` that connects to the interface input.
export interface InterfaceInputConsumer {
  primPath: string
  name: string
}

// Map keyed by an interface input's bare name → its consumer inputs.
export type InterfaceInputConsumersMap = Map<string, InterfaceInputConsumer[]>

// The connectable shading prim types (those with a registered
// UsdShadeConnectableAPIBehavior). Material IS-A NodeGraph.
function isConnectable(typeName: string): boolean {
  return typeName === 'Shader' || typeName === 'NodeGraph' || typeName === 'Material'
}

// True for prim types that are node-graphs (IsA<UsdShadeNodeGraph>): NodeGraph
// and its subclass Material.
function isNodeGraphType(typeName: string): boolean {
  return typeName === 'NodeGraph' || typeName === 'Material'
}
